//! What the machine says it is: `uname`, `sethostname`, `setdomainname` and
//! `sysinfo`.
//!
//! Three syscalls whose whole content is two guest structs and where each field
//! of them comes from. Both structs are generated by `build.rs` — `struct
//! sys_info` has three explicit padding fields and `struct uname` is six 65-byte
//! arrays, and a wrong offset in either is a number a program reads as
//! something else entirely.
//!
//! # Every string here is bounded, and one of them had to be
//!
//! Five of `uname`'s six fields are constants this kernel chooses. The sixth is
//! the **host's** node name, or whatever an embedder put in
//! `uname_hostname_override`, and it goes into 65 bytes. A host called something
//! longer used to end the process outright: macOS compiles `strcpy` to
//! `__builtin___strcpy_chk` against the field's known size, and the overflow
//! trapped in `__chk_fail_overflow` before the guest saw anything. A CI runner
//! was named exactly that long and every guest command on it died. Linux
//! truncates, so truncating matches it — and in Rust the field is a fixed-size
//! array that a longer string cannot be written past at all.
//!
//! # The two globals stay C symbols
//!
//! `uname_version` and `uname_hostname_override` are how an **embedder** sets
//! what a guest sees, so their symbol names are an interface this repository
//! does not own. They are `#[no_mangle]` statics for that reason, and not for
//! any reason internal to this crate.

#![allow(non_upper_case_globals)]

use std::ffi::c_char;

use guest_errno::Errno;
use strace::strace;
use usercopy::GuestMem;

// The shared Rust types and constants are re-exported by kernel-taskview.
pub use taskview::ffi;

// ---------------------------------------------------------------------------
// The embedder's two knobs
// ---------------------------------------------------------------------------

// Writable `static mut` C strings until 2026-10-17, which an embedder
// assigned and every `uname` read in an `unsafe` block; copied in by a call
// now, and owned here.

/// What goes in `uts.version`, before the build stamp; `None` is the default.
static VERSION: std::sync::RwLock<Option<Vec<u8>>> = std::sync::RwLock::new(None);

/// What goes in `uts.hostname` in place of the host's node name; `None` is the
/// host's.
static HOSTNAME_OVERRIDE: std::sync::RwLock<Option<Vec<u8>>> = std::sync::RwLock::new(None);

fn read(slot: &std::sync::RwLock<Option<Vec<u8>>>) -> Option<Vec<u8>> {
    slot.read().unwrap_or_else(|e| e.into_inner()).clone()
}

fn store(slot: &std::sync::RwLock<Option<Vec<u8>>>, value: Option<&[u8]>) {
    *slot.write().unwrap_or_else(|e| e.into_inner()) = value.map(<[u8]>::to_vec);
}

/// Replace `uts.version`'s text; `None` restores the default.
pub fn set_uname_version(version: Option<&[u8]>) {
    store(&VERSION, version);
}

/// Report `hostname` instead of the host's node name; `None` reports the
/// host's again.
pub fn set_hostname_override(hostname: Option<&[u8]>) {
    store(&HOSTNAME_OVERRIDE, hostname);
}

/// The C spelling of [`set_hostname_override`], copied; null clears it.
///
/// # Safety
/// `hostname` is null or a NUL-terminated string.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn iul_set_hostname(hostname: *const c_char) {
    // SAFETY: the caller's contract.
    let name = (!hostname.is_null()).then(|| unsafe { std::ffi::CStr::from_ptr(hostname) });
    set_hostname_override(name.map(std::ffi::CStr::to_bytes));
}

/// The C spelling of [`set_uname_version`].
///
/// # Safety
/// As [`iul_set_hostname`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn iul_set_uname_version(version: *const c_char) {
    // SAFETY: the caller's contract.
    let v = (!version.is_null()).then(|| unsafe { std::ffi::CStr::from_ptr(version) });
    set_uname_version(v.map(std::ffi::CStr::to_bytes));
}

/// The build's date and time, as the C's `__DATE__ " " __TIME__` was.
const BUILD_STAMP: &str = env!("IUL_BUILD_STAMP");

// ---------------------------------------------------------------------------
// uname
// ---------------------------------------------------------------------------

/// Copy `s` into `field`, truncating and always leaving a terminator.
///
/// The whole reason this is a function: `field` is 65 bytes and `s` is not
/// bounded by anything this kernel controls. A truncated node name is what
/// Linux answers; an overrun is what the C did.
fn put(field: &mut [c_char], s: &str) {
    let room = field.len() - 1;
    let bytes = s.as_bytes();
    let n = bytes.len().min(room);
    for (slot, b) in field.iter_mut().zip(bytes[..n].iter()) {
        *slot = *b as c_char;
    }
    for slot in field[n..].iter_mut() {
        *slot = 0;
    }
}

/// The names a guest set with `sethostname` and `setdomainname`, which win
/// over the embedder's override and the host's own name from then on. One UTS
/// namespace, as there is one of everything else here. Both used to be
/// `EPERM` for everyone, root included, so `hostname foo` in a guest failed.
#[derive(Default)]
struct SetNames {
    hostname: Option<Vec<u8>>,
    domainname: Option<Vec<u8>>,
}

static SET_NAMES: std::sync::Mutex<SetNames> = std::sync::Mutex::new(SetNames {
    hostname: None,
    domainname: None,
});

/// `__NEW_UTS_LEN`: the most either name may be, not counting a terminator.
pub const UTS_LEN: u32 = 64;

/// `sethostname`'s and `setdomainname`'s rule, in Linux's order: the
/// capability first, so an unprivileged caller with a bad length is told
/// `EPERM`; then the length.
pub(crate) fn set_name_ok(sys_admin: bool, len: u32) -> Result<(), Errno> {
    if !sys_admin {
        return Err(Errno::EPERM);
    }
    if len > UTS_LEN {
        return Err(Errno::EINVAL);
    }
    Ok(())
}

fn hostname() -> Vec<u8> {
    if let Some(h) = &SET_NAMES.lock().unwrap_or_else(|e| e.into_inner()).hostname {
        return h.clone();
    }
    if let Some(name) = read(&HOSTNAME_OVERRIDE).filter(|n| !n.is_empty()) {
        return name;
    }
    rustix::system::uname().nodename().to_bytes().to_vec()
}

/// `(none)`, as Linux reports a domain nobody has set.
fn domainname() -> Vec<u8> {
    SET_NAMES
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .domainname
        .clone()
        .unwrap_or_else(|| b"(none)".to_vec())
}

fn put_bytes(field: &mut [c_char], bytes: &[u8]) {
    let room = field.len() - 1;
    let n = bytes.len().min(room);
    for (slot, b) in field.iter_mut().zip(bytes[..n].iter()) {
        *slot = *b as c_char;
    }
    for slot in field[n..].iter_mut() {
        *slot = 0;
    }
}

/// The shared body of the two setters: the rule, the copy, the store.
fn set_name(
    addr: u64,
    len: u32,
    which: fn(&mut SetNames) -> &mut Option<Vec<u8>>,
) -> Result<(), Errno> {
    set_name_ok(taskview::capable(taskview::caps::CAP_SYS_ADMIN), len)?;
    let mut name = vec![0u8; len as usize];
    if GuestMem::current().read(addr, &mut name) != 0 {
        return Err(Errno::EFAULT);
    }
    // Linux keeps the bytes up to the length given and a NUL inside them ends
    // the name where it is read back; ending it here once is the same answer.
    if let Some(end) = name.iter().position(|&b| b == 0) {
        name.truncate(end);
    }
    *which(&mut SET_NAMES.lock().unwrap_or_else(|e| e.into_inner())) = Some(name);
    Ok(())
}

/// What this machine says it is.
pub fn uname() -> ffi::uname {
    let mut uts = ffi::uname::default();
    put(&mut uts.system, "Linux");
    put_bytes(&mut uts.hostname, &hostname());
    // The release a guest is told to expect. It was `4.20.69` until 2026-11-11,
    // which hid every later syscall implemented
    // here (`pidfd_send_signal` 5.1, `clone3` and `pidfd_open` 5.3,
    // `faccessat2` 5.8, `close_range` 5.9) from a caller that gates on `uname`.
    //
    // 7.0 does not mean every 7.0 syscall exists. What is missing answers
    // `ENOSYS` (`syscall_stub`, `syscall_silent_stub`, and any number past
    // `SYSCALL_TABLE_SIZE`), which is also what a real 7.0 built without
    // `io_uring`, `bpf` or `landlock` answers, so a program that probes at run
    // time takes its fallback. A program that assumes a feature from the
    // version alone does not; implement the syscall rather than lowering this.
    put(&mut uts.release, "7.0.0-iul");
    let version = read(&VERSION).unwrap_or_else(|| b"SUPER AWESOME".to_vec());
    put(&mut uts.version, &format!("{} {BUILD_STAMP}", String::from_utf8_lossy(&version)));
    put(&mut uts.arch, "aarch64");
    put_bytes(&mut uts.domain, &domainname());
    uts
}

pub fn sys_uname(uts_addr: u64) -> Result<(), Errno> {
    strace!("uname({uts_addr:#x})");
    if GuestMem::current().write_value(uts_addr, &uname()) != 0 {
        return Err(Errno::EFAULT);
    }
    Ok(())
}

/// Always `EPERM`.
///
/// Linux wants `CAP_SYS_ADMIN` in the UTS namespace, and there are no UTS
/// namespaces here — one node name for the whole emulator, which a guest
/// changing would change for the embedder as well. `uname_hostname_override` is
/// the interface for setting it, and it is the embedder's.
pub fn sys_sethostname(hostname_addr: u64, len: u32) -> Result<(), Errno> {
    strace!("sethostname({hostname_addr:#x}, {len})");
    set_name(hostname_addr, len, |n| &mut n.hostname)
}

pub fn sys_setdomainname(name_addr: u64, len: u32) -> Result<(), Errno> {
    strace!("setdomainname({name_addr:#x}, {len})");
    set_name(name_addr, len, |n| &mut n.domainname)
}

// ---------------------------------------------------------------------------
// sysinfo
// ---------------------------------------------------------------------------

use kernel_hoststats::get_uptime;
/// What a guest is told the machine has, and how much of it is spoken for.
///
/// Both are `crates/kernel/hoststats`, because `/proc/meminfo` answers the same
/// two questions and the two used to answer them differently -- see the comment
/// on `GUEST_MAX_RAM` there.
use kernel_hoststats::{guest_free_ram, guest_total_ram};

pub fn sys_sysinfo(info_addr: u64) -> Result<(), Errno> {
    strace!("sysinfo({info_addr:#x})");
    let mut info = ffi::sys_info::default();

    let uptime = get_uptime();
    // `sysinfo` counts in seconds; `uptime_ticks` is hundredths.
    info.uptime = uptime.uptime_ticks / 100;
    info.loads = [uptime.load_1m, uptime.load_5m, uptime.load_15m];

    let total = guest_total_ram();
    info.totalram = total;
    info.freeram = guest_free_ram(total, pagetable::anonbudget::anon_pages_used());
    info.mem_unit = 1;

    // The number of processes, which this reported as zero until the pid
    // registry started counting them. `nproc`, monitoring tools and anything
    // sizing a pool read it.
    info.procs = kernel_pids::PidsGuard::take().task_count() as u16;

    // What used to be here: a guess that a caller whose buffer already held a
    // non-zero value with a zero low byte was glibc's abort() path passing the
    // address of __stack_chk_guard, and that the first eight bytes should
    // therefore be left alone. It was removed rather than narrowed, and the
    // reasons are in
    // docs/changelog/ -- the short version is that an aligned pointer is the
    // commonest thing to find on an uninitialised stack and its low byte is
    // zero, so the guess fired for ordinary callers and left them reading a
    // leftover address as their uptime.

    if GuestMem::current().write_value(info_addr, &info) != 0 {
        return Err(Errno::EFAULT);
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    /// `sethostname`'s rule: the capability is asked for before the length,
    /// so an unprivileged caller with a bad length is `EPERM` and a
    /// privileged one with a length past `__NEW_UTS_LEN` is `EINVAL`. It
    /// used to be `EPERM` for everyone.
    #[test]
    fn a_hostname_is_roots_to_set_and_sixty_four_bytes_at_most() {
        assert_eq!(super::set_name_ok(false, 5), Err(Errno::EPERM));
        assert_eq!(
            super::set_name_ok(false, 1000),
            Err(Errno::EPERM),
            "EPERM before EINVAL"
        );
        assert_eq!(
            super::set_name_ok(true, 0),
            Ok(()),
            "an empty name is a name"
        );
        assert_eq!(super::set_name_ok(true, 64), Ok(()));
        assert_eq!(super::set_name_ok(true, 65), Err(Errno::EINVAL));
        assert_eq!(
            super::set_name_ok(true, u32::MAX),
            Err(Errno::EINVAL),
            "a negative length, as the register holds it"
        );
    }

    use super::*;

    fn read(field: &[c_char]) -> String {
        let n = field.iter().position(|&c| c == 0).unwrap_or(field.len());
        field[..n].iter().map(|&c| c as u8 as char).collect()
    }

    /// The one field that is not this kernel's own constant. 65 bytes, and the
    /// string comes from the host.
    #[test]
    fn a_name_longer_than_the_field_is_truncated_and_terminated() {
        let mut field = [1 as c_char; 65];
        put(&mut field, &"x".repeat(200));
        assert_eq!(read(&field).len(), 64);
        assert_eq!(field[64], 0, "the terminator is inside the field");

        // Exactly the field size, which is the off-by-one either way.
        let mut field = [1 as c_char; 65];
        put(&mut field, &"y".repeat(65));
        assert_eq!(read(&field).len(), 64);
        assert_eq!(field[64], 0);

        // One short of it fits whole.
        let mut field = [1 as c_char; 65];
        put(&mut field, &"z".repeat(64));
        assert_eq!(read(&field).len(), 64);
        assert_eq!(field[64], 0);
    }

    /// Everything past the string is zeroed, so a field written twice does not
    /// leave the longer answer's tail behind.
    #[test]
    fn the_rest_of_the_field_is_cleared() {
        let mut field = [b'?' as c_char; 65];
        put(&mut field, "short");
        assert_eq!(read(&field), "short");
        assert!(field[5..].iter().all(|&c| c == 0));
    }

    #[test]
    fn an_empty_name_is_an_empty_field() {
        let mut field = [b'?' as c_char; 65];
        put(&mut field, "");
        assert_eq!(read(&field), "");
        assert!(field.iter().all(|&c| c == 0));
    }

    /// 112 bytes with three explicit padding fields. Generated, so this is a
    /// check on the generation rather than on a copy — but a guest reads
    /// `totalram` at a fixed offset and gets the uptime if it moves.
    /// `uname` against a host name longer than the field it goes in.
    ///
    /// `tests/unit/uname_test.c` was this until 2026-09-08. The bug it was
    /// written for is that the call **did not return**: macOS compiles `strcpy`
    /// to `__builtin___strcpy_chk` against the field's known size, and a CI
    /// runner named longer than 64 bytes trapped in `__chk_fail_overflow`
    /// before the guest saw anything. Every command on that machine died.
    ///
    /// In Rust the field is a fixed-size array a longer string cannot be
    /// written past at all, so what is left to check is that it truncates to
    /// the *front* of the name, terminates inside the field, and does not
    /// disturb its neighbours.
    ///
    /// The three tests above cover `put_bytes` in isolation; this one covers
    /// the caller, which is where the whole struct is filled.
    #[test]
    fn a_long_hostname_is_truncated_and_the_other_fields_survive() {
        const LONG: &str = "a-host-with-a-name-far-longer-than-sixty-five-bytes-\
                            which-is-all-the-room-the-field-has-and-more";
        let long = std::ffi::CString::new(LONG.replace(' ', "")).unwrap();
        super::set_hostname_override(Some(long.as_bytes()));

        let mut uts = super::uname();

        let field = &uts.hostname;
        assert_eq!(field[field.len() - 1], 0, "terminated inside the field");
        let got: Vec<u8> = field[..field.len() - 1].iter().map(|&c| c as u8).collect();
        let want = long.as_bytes();
        assert_eq!(got.len(), 64);
        assert_eq!(
            &got[..],
            &want[..64],
            "the front of the name, not something else"
        );

        // A truncating copy that scribbled over its neighbours shows up here.
        let cstr = |f: &[c_char]| {
            let b: Vec<u8> = f
                .iter()
                .take_while(|&&c| c != 0)
                .map(|&c| c as u8)
                .collect();
            String::from_utf8(b).unwrap()
        };
        assert_eq!(cstr(&uts.system), "Linux");
        assert_eq!(cstr(&uts.arch), "aarch64");
        assert_eq!(cstr(&uts.release), "7.0.0-iul");
        assert_eq!(cstr(&uts.domain), "(none)");
        assert!(!cstr(&uts.version).is_empty());

        // Without an override it reports the machine's own name, which still
        // has to fit.
        super::set_hostname_override(None);
        uts = super::uname();
        assert!(uts.hostname[uts.hostname.len() - 1] == 0);
    }

    #[test]
    fn the_guest_structs_are_the_size_the_guest_expects() {
        assert_eq!(std::mem::size_of::<ffi::sys_info>(), 112);
        assert_eq!(std::mem::size_of::<ffi::uname>(), 65 * 6);
    }
}
